INSERT INTO public.car_pages VALUES ('3cca3184-a311-4624-b1c2-845b068c08e7', 'ed05f534-f9db-4ff3-86d0-9fc52a600d28', 'Тачка кольору всесвіту🌌', '<p>VW Tiguan — універсальний SUV із німецьким характером.<br />
Доступна топова версія:</p>
<p>2.0 TSI — 250 к.с., 370 Нм, 0–100 км/год за 6,2 с<br />
Повний привід 4MOTION, швидка DSG-передача, стабільна тяга та драйв як у GTI — але з простором і зручністю кросовера.</p>
<p>Tiguan за підпискою — це коли маєш все, що треба, без кредитів, страхів і компромісів.</p>

<p>Салон Tiguan — для тих, хто цінує простір і порядок.</p>
<p>Мультимедіа з 8&#8243; або 10&#8243; дисплеєм, повна підтримка Apple CarPlay / Android Auto</p>
<p>Віртуальна панель приладів</p>
<p>Електропривод багажника, адаптивне підсвічування</p>
<p>Комфортне сидіння з регулюванням попереку</p>
<p>Ідеальний для сім’ї, подорожей і міських справ. А з авто за підпискою — він ще й твій без зайвих клопотів.</p>

<p>Tiguan — універсальний SUV з бензиновим мотором на 250 к.с., повним приводом і DSG. Комфорт для щоденного життя й подорожей.</p>
<p>✔ Повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ Trade-in, драйвер-сервіс, підтримка 24/7<br />
✔ Оформлення за 29 хв без перевірок і банківських документів</p>
<p>Volkswagen Tiguan — коли все працює для тебе, а не ти для авто</p>
', NULL, '[{"author": "Григорій Осадчий", "rating": 5, "comment": "За пропозицією засновника Drivovo-Club Maxim Solovyov взяв на вихідні у тест-драйв новий Volkswagen Tiguan R-line. Не має сенсу писати про всі сучасні плюшки які роблять водіння безпечним та комфортним, в новому Тігуані вони звісно є, про це все можна детально подивитись в професійних описах. Максим з турботою зробив огляд основних перед початком тест-драйву. Можу зазначити, що мені сподобався дизайн машини, місця всередині багато для всієї сімї. Дощові вихідні в машині пройшли затишно, як в пересуванні містом по проспекту (в режимі Еко всі набори та скидання швидкості і маневри дуже плавні, наче в кріслі вдома), так і коли довелось тягнутись по вуличках, проїздах та парковках. Очікування були перевершені, враження дуже приємні. Як кажуть у Drivovo-Club Drive it Easy. І звісно памятаймо, що можливості комфортного пересування у авто не було б без успіхів ЗСУ, Героям Слава!", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/294824174_606739224170374_2212901346118307789_n.jpg"}]', 'Volkswagen Tiguan R-Line від Drivovo: Ваш автомобіль по підписці з передовими технологіями', 'Підписка на авто з Drivovo: замовте Volkswagen Tiguan R-Line з потужністю 220 к.с. і 4MOTION приводом. Використовуйте передові функції, включаючи адаптивний круїз-контроль та систему безпеки Side Assist, а також насолоджуйтесь високоякісним аудіо від Harman Kardon.');
INSERT INTO public.car_pages VALUES ('733833f7-c97e-4e54-8b9d-96be3c55fe7d', '59a8b950-1194-4a76-a12b-29890e001fe0', 'Тачка — це перепустка в Drivovo Pride', '<p>Audi Q5 доступна у бензиновій версії 2.0 TFSI (265 к.с., 0–100 км/год за 6,1 с) і дизельній 2.0 TDI (204 к.с., 7,6 с до 100 км/год). Повний привід quattro, 7-ступенева автоматична коробка S tronic — ідеальне поєднання потужності та контролю на будь-якому покритті. Обирай Audi Q5 за підпискою — і відчуй преміальний драйв без переплат і довгих оформлень.</p>

<p>Всередині Audi Q5 — поєднання стриманого преміуму та функціонального комфорту. Віртуальна панель приладів Audi Virtual Cockpit, мультимедіа MMI з 10,1&#8243; дисплеєм, двозонний клімат-контроль, світлодіодне підсвічування, акустика Bang &amp; Olufsen (опційно) — усе для твого затишку. Завдяки авто за підпискою ти отримуєш максимум без зобов’язань.</p>

<p>Усе включено — і нічого зайвого. Audi Q5 оснащена системами попередження зіткнень, допомогою при паркуванні, камерою заднього виду, утриманням у смузі та адаптивним круїз-контролем. А разом із підпискою ти отримуєш КАСКО, страхування, GPS-трекер, технічне обслуговування і заміну гуми. Сів — і поїхав.</p>
', NULL, '[{"author": "Горбенко Андрій", "rating": 5, "comment": "Зрозумійте я не отримую якогось кайфу від швидкості. У мене одне око і я не бачу 3D як більшість з вас. Тому швидке авто мені це так само як і не швидке картинка та сама. А от чітке керування я люблю. Коли ти точно знаєш, що хочешь, робиш це і машина виконує саме те чого ти хочеш. Ти не пристосовуєшся під неї, а вона під тебе вона просто вона розуміє чого ти хочеш і робить це. Сидячі в Ауді питаєш себе а навіщо інші машини взагалі? Ну бо при бажанні сюди залізуть дві дитини і коляска. Що не правда всім буде тісно)))) Але коли сидиш в Ауді про це не думаєш. Думаєш як тобі в ній приємно. Потім коли я віддав машину я згадав, що у мене в ній грала тільки життєрадісна музика ну отак я обирав. У висновку я попрошу вас спробувати поводити хоча б на тест драйві щось таке. Або Ауді А4, або BMW 3 або напишіть що треба поводити, ті хто розуміється на таких автомобілях. Це як відчути, що світ ширший. Це як слухати все життя поп, шансон і дитячі пісеньки, а потім почути рок-н-ролл. Ну і я так думаю, що кожен має хоча б рік в своєму житті поволодіти такою машиною. Щоб життя було повнішим. Дякую Drivovo-Club , що відкрили очі на світ автомобілів.", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/245997274_10227091570218929_1789616788653253511_n.jpg"}]', 'Audi Q5: Розкіш, Комфорт та Потужність у Кожному Заїзді', 'Відкрийте світ розкоші з Audi Q5 — потужним кросовером, що поєднує вишуканий дизайн та передові технології. Оформіть підписку на авто в Drivovo та насолоджуйтесь неперевершеним комфортом, простором та динамікою під час кожної поїздки. Відчуйте різницю з Audi Q5 вже сьогодні!');
INSERT INTO public.car_pages VALUES ('5c15103f-0056-44f3-a0e6-de834f9bc1c0', '4be2ac97-7b2c-4026-a4db-e8857ed6cfb3', 'Тачка — це перепустка в Drivovo Pride', '<p>Audi Q7 — це поєднання солідної маси та динаміки преміум-рівня. Бензинові та дизельні мотори видають від 231 до 340 к.с., що гарантує плавне прискорення та впевнене обгонне маневрування.<br />
Бензиновий Q7 55 TFSI (340 к.с.) розганяється до 100 км/год за 5,9 секунди, а дизельна версія 45 TDI (231 к.с.) — за 7,1 секунди.<br />
З Audi Q7 у підписці від Drivovo ви отримуєте не просто авто, а драйв без компромісів — потужний, стабільний і завжди готовий до нових маршрутів.</p>

<p>Салон Audi Q7 — це еталон преміальної ергономіки та цифрових рішень. Просторий 7-місний інтер’єр із віртуальною панеллю приладів Audi Virtual Cockpit, двома сенсорними дисплеями MMI та адаптивним підсвічуванням створює атмосферу сучасного комфорту.<br />
Автомобіль підтримує Apple CarPlay, Android Auto, має навігацію, голосове керування та Bang &amp; Olufsen у топових комплектаціях.<br />
У підписці на Audi Q7 від Drivovo технології — не бонус, а стандарт.</p>

<p>Audi Q7 — це великий преміум SUV з двигунами до 340 к.с., повним приводом і простором для 7 пасажирів. Він дарує впевненість у русі та сервісі.</p>
<p>✔ повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ trade-in, супровід на СТО, підтримка 24/7<br />
✔ оформлення за 29 хв без довідок і перевірок</p>
<p>Audi Q7 — це бізнес-клас на колесах: комфорт і турбота вже в комплекті</p>
', NULL, '[{"author": "Олександр Джупина", "rating": 5, "comment": "Solovyov Maxim , по-перше, дякую за подарунок на др “тест драйв Audi Q7”. Це було потужно та емоційно. А, по-друге, якби я працював в салоні Audi, то саме так описав цей автомобіль «висока якість виконання та потужний двигун Audi Q7 залишає незабутнє враження. Просторий салон, передові технології та відмінна ергономіка роблять кожну поїздку комфортною. Завдяки високій маневреності та продуманій системі безпеки, цей автомобіль вражає якістю та відчуттям розкоші». Але ми люді прості, тому слухайте реальний відгук: 1. Audi Q7 це літак. Тулить дай Бог. 3 л дизелю вистачає з головою. Щоб ви розуміли, тачка не прискорюються, а вистрілює. 2. Салон великий та якісний. Сідаєш у ці крісла, і таке відчуття, що ніби вони тебе обіймуть своїми рученятами і гріють тобі спинку. 3. По кнопочкам- все системно та оптимізовано в стилі німців. Хотів до чогось причепитися, але трясця не вийшло. 4. Якість матеріалів на висоті. 5. Дуже крута штука прям мега круть це рідні асистенти допомоги водієві. Це топ. Особисто протестував автоматичну парковку. Машинка сама паркується, а це вражає. І головне. Що все рівно і чітко. Висновок: офігенна тачка, економічна, мʼяка по підвісці, технологічна, емоційна. Шо не сподобалося: 1. Відсутні пороги. Треба звикнути, щоб з неї вилазити. 2. Машинка на свого клієнта. Щодо мене, то я б розглядав дану машинку як другу машину для сімʼї. Якщо от плям покласти руку на серце, то аудюха не закриє мій слот по моєму хоббі рибалка. По-перше , не всюди вона проїде, по-друге, ну дуже вона елегантна. А так по місту, по трасі, мінімально виїхати на природу, то буде ок. Всім дякую. Особливо хлопцям з Drivovo-Club . Мега клієнтоорієнтовані пацани.", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/424888862_10225305508997259_869204859990137290_n.jpg"}]', 'Audi Q7 за підпискою від Drivovo - Ідеальне авто для вашого комфорту', 'Оформіть підписку на Audi Q7 50 TDI Quattro S Line: дизельний двигун 286 к.с., 8-ступінчата Tiptronic, 4-зональний клімат-контроль, адаптивна підвіска, та Bang & Olufsen звук. Люксовий комфорт та вражаючі технології в одному авто');
INSERT INTO public.car_pages VALUES ('58df4510-29f4-4e31-9511-ea244c21e9aa', 'd875c8a9-c080-4904-9a2a-171c1d8be473', 'Audi Q8 50 TDI quattro S line', '<p>Audi Q8 — це розкішний позашляховик із характером купе.<br />
Доступні бензинові та дизельні версії:</p>
<p>50 TDI — 3.0 дизель, 286 к.с., 600 Нм, 0–100 км/год за 6,1 с</p>
<p>Фірмова система quattro та адаптивна пневмопідвіска забезпечують плавність ходу і впевненість на будь-якій дорозі.<br />
Audi Q8 в підписці — це статус, який не потребує виправдань.</p>

<p>Інтер’єр Audi Q8 — це простір тиші, технологій і естетики.<br />
Три дисплеї MMI Touch Response, цифрова панель Virtual Cockpit, сидіння з вентиляцією та масажем, преміальна акустика Bang &amp; Olufsen.<br />
Продумане до деталей ambient-підсвічування та безрамкові екрани — усе говорить про сучасний смак.<br />
З авто за підпискою від Drivovo вам доступні ці технології вже сьогодні — без кредитів і очікувань.</p>

<p>Audi Q8 поєднує в собі спортивний характер купе та комфорт розкішного SUV. Потужність до 340 к.с., quattro і гібридна система — авто для сучасного темпу.</p>
<p>✔ повне страхування, трекер, онлайн-моніторинг<br />
✔ ТО, шинний сервіс, підмінне авто<br />
✔ trade-in, підтримка 24/7, супровід на СТО<br />
✔ оформлення за 29 хв без фінмоніторингу</p>
<p>У підписці Audi Q8 — це преміум-клас, який не змушує чекати</p>
', NULL, '[{"author": "Владислав Ткачук", "rating": 5, "comment": "Кермуєш автівкою так, як живеш. Цю метафору від Yuriy Koziy часто згадую, як сідаю за кермо. Так було не завжди, але зараз мій стиль — розслаблені та усвідомлені подорожі. Не просто з точки А до Б. А так, щоб помітити цікаве та подумати про важливе. Здається, #audi #q8 чудово для цього підходить. Не дивно, наскільки ця автівка комфортна. Дивовижно, наскільки швидко я до неї звик. До чималих габаритів призвичаївся за кілька годин. Отримувати задоволення — значно раніше. По відчуттям нагадує #rangerover . За потреби може показати драйв, але набагато приємніше просто плисти у потоці. Бажаючих підрізати чи зганяти в інший ряд зазвичай небагато. Не думав, що хотітиму Audi Q8. Тепер хочу За два дні тестдрайву ми здружилися та звикли одне до одного. Дякую, Maksym Soloviov за цей подарунок! Дякую команді Drivovo-Club за чудовий сервіс. На отримання та повернення коштовної автівки — мінімум часу та документів. Максимум — людського спілкування та турботи. Це приємно вражає. Дякую за цікавий досвід.", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/34323978_10155645924257606_3138239922087919616_n.jpg"}]', 'Drivovo пропонує Audi Q8 Quattro S Line за підпискою в Україні', 'З Drivovo отримайте Audi Q8 Quattro S Line: 286 к.с., адаптивна підвіска, 4-зональний клімат-контроль, Bang & Olufsen звук, нічне бачення. Першокласний комфорт та безпека.');
INSERT INTO public.car_pages VALUES ('a388f440-7754-452e-bb62-fc93bfc33344', '36b9355c-86e4-4e8f-98be-7d0a65d4d122', 'Тачка — це перепустка в Drivovo Pride', '<p>BMW X5 — це потужний і стильний SUV, що так і манить.<br />
Під капотом — 3.0-літровий 6-циліндровий двигун на 340 к.с., який розганяється до 100 км/год за 5,5 секунди. Це не просто швидкість, а повний контроль на будь-якому типі покриття.<br />
З повним приводом xDrive і адаптивною підвіскою, BMW X5 забезпечує неймовірну стабільність і комфорт навіть на високих швидкостях.<br />
З підпискою на BMW X5 ти отримуєш безкомпромісну динаміку без турбот.</p>

<p>У BMW X5 все створено для водія: точне керування, інтуїтивно зрозумілий інтерфейс і передові технології, що працюють на тебе.<br />
Підписка на BMW X5 — це максимум технологій без додаткових витрат.</p>

<p>BMW X5 — це 3.0 л дизель на 265 к.с., повний привід xDrive і преміальна стабільність. Створений для тих, хто знає, чого хоче.</p>
<p>✔ повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ trade-in, супровід на СТО, підтримка 24/7<br />
✔ оформлення за 29 хв без довідок і перевірок</p>
<p>X5 — ти керуєш, а про решту Drivovo вже подбали</p>
', NULL, '[{"author": "Ліновецька Юлія", "rating": 5, "comment": "Маю визнати, що я помилялась… Мені завжди здавалося, що BMW — переоцінене авто і, ясно, що там щось розпиляють, бо всі становляться неадекватними… Перевірила — ні, то не в машині біда 🫣 Варто було сісти за кермо, і все… Спробую притушити свої емоції і написати щось без стонів 😁 По-перше, салон 😌🤌 Я в дикому захваті (не вийшло без емоцій 💁🏻‍♀️), бо відчуваєш себе капітаном космічного корабля, де 100500 налаштувань, але все інтуїтивно зрозуміло. Технологічно, сучасно, естетично, функціонально й ергономічно. Від підстаканників до ковшів. Я б не змогла придертись, якби і хотіла. По-друге — баланс жорсткості/мʼякості ідеальний. Не гойдається по дорозі, але й не прикачує. Динамічна, маневрена, керована. Але так приємно в ній просто котитись і музичку слухати, а звук тут просто сироп для ніжних вушок меломана ☺️ По-третє — обоже, тут найкрутіша камера з усіх. І 3D паркування навіть. Я вже не знаю, що треба зробити, щоб не паркуватися ідеально. Хоча розміри чималі 🙈 Витрата… Не дивилась, якщо чесно. Бо в BMW не думаєш про дрібниці життя 🫣 До речі! Поворотники працюють, не вірте їм 🤫🌚 Ну, коротше, я ще довго можу тут пищати, але треба просто брати і їхати до Drivovo — це ж вони таку красу мають в автопарку 🐥💪🏻", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/516037983_25262671170035900_5606138371576978690_n.jpg"}]', 'Drivovo пропонує BMW X5 xDrive 30d з пневмопідвіскою за підпискою', 'Замовляйте BMW X5 xDrive 30d від Drivovo: 265 к.с., адаптивна пневмопідвіска, розгін до 100 км/год за 6.5 сек. Ваш комфорт та безпека на максимумі з підпискою на авто');
INSERT INTO public.car_pages VALUES ('0bddfe61-dc0f-4fbd-8463-b4dc756af318', '77fc1d11-001b-42a7-856c-e10a3881b8fa', 'Тобі досі не знайоме це авто? 😳', '<p>Cupra Formentor VZ — коли кросовер має темперамент.</p>
<p>2.0 TSI, 310 к.с., повний привід 4Drive</p>
<p>Розгін 4,9 с до 100 км/год</p>
<p>Робот DSG 7-ступеневий, адаптивне шасі (DCC)</p>
<p>Це не просто швидко. Це емоційно. Це VZ — Veloz (швидкий).<br />
Обирай Formentor у підписку, якщо шукаєш щось дике, але зручне.</p>

<p>Всередині — як у спорткарі, тільки з комфортом.</p>
<p>Спортивні ковші CUPRA зі шкіри</p>
<p>Амбієнтне підсвічування</p>
<p>Віртуальна панель і 12&#8243; мультимедіа з бездротовим CarPlay</p>
<p>Безрамкове дзеркало, безключовий доступ, панорама</p>
<p>Це не просто салон — це твоя кокпіт-зона.<br />
Cupra Formentor за підпискою — твій стиль у кожній деталі.</p>

<p>Formentor VZ — 310 к.с., DSG, повний привід і дизайн, що виділяється. Компактний спорт-SUV з диким характером.</p>
<p>✔ Повне страхування: КАСКО, ОСЦПВ, GAP, трекер<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ Trade-in, супровід на СТО, підтримка 24/7<br />
✔ Оформлення без довідок, лише за наявності паспорта і прав</p>
<p>Cupra Formentor — це коли авто заряджене, а ти — спокійний</p>
', NULL, '[{"author": "Вікторія Наливайко", "rating": 5, "comment": "В кожного свої залежності в мене от автівки *колись мріяла про другу освіту автомеханіка Зараз ця мрія трансформувалась в бажання їздити і бажано багато) а ще, тестувати нові авто та намагатись зрозуміти їх самоідентичність, чим вони різняться, що мені в кожній з них подобається, їх характер. От наприклад ця Купра дуже круто себе веде на трасі, тримає кермо та на 180 навіть не відчуваєш, що це 180. Про зовнішній вигляд мовчу, слина тече Але характеру замало (але ж і Купри бувають різні ). А от Тігуан мій, хоч і 15 року, але турбіна робить свою справу і на світлофорі я вириваюсь вперед (тут мене можна трішки затюкати, бо я чуть-чуть шалений драйвер) Дякую Drivovo-Club що з вами я можу реалізовувати свою мрію. Це вже 3 машинка від Drivovo але не остання Наступні на тест-драйв Toyota RAV4, Volvo XC60. Якщо ви такий же автолюбитель, подружіться та затестуйте авто від Drivovo Maksym Soloviov дякую за супер сервіс", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/354468382_3194941727465400_6691273696264086344_n.jpg"}]', 'Drivovo: Ваш шлях до Formentor VZ — підписка авто на топові умови', 'Переживіть драйв з Formentor VZ, пропонований Drivovo. 310 к.с., панорамний дах, адаптивна підвіска, і розширена мультимедія. Перевага підписки на автомобіль для вимогливих водіїв');
INSERT INTO public.car_pages VALUES ('b69d9b05-2b16-4c2f-9f2c-0bc6aee86f42', 'e908ecea-321b-4273-bf88-32e42bdc8e3e', 'Тачка — це перепустка в Drivovo Pride', '<p>Mercedes GLS не просто вражає — він захоплює. Потужний 3.0 л V6, 367 к.с. і розгін 6.1 секунда до 100, ти відчуваєш не просто швидкість, а повний контроль за кожним рухом. Спортивна динаміка в поєднанні з розкішшю — однозначно про нього.</p>

<p>Кожна поїздка в Mercedes GLS — це подорож у світ технологій і комфорту. Від першого дотику до керма ти розумієш, що це авто шикарне. Просторі сидіння, віртуальна панель приладів, акустика Burmester і мультимедійна система з підтримкою Apple CarPlay та Android Auto — усе, що необхідно для справжнього преміум-досвіду.</p>

<p>GLS — це 367 к.с., 3.0 л V6, 4MATIC, 7 місць і рівень розкоші, який справді відчувається. Простір, міць і технології в одному SUV.</p>
<p>✔ повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, шини, підмінне авто, шинний сервіс<br />
✔ trade-in, консьєрж-супровід, підтримка 24/7<br />
✔ оформлення за 29 хв без фінконтролю</p>
<p>Mercedes GLS — не просто авто, а престижна територія руху</p>
', NULL, '[{"author": "Володимир Швець", "rating": 5, "comment": "100 km зручно, комфортно, кайфово🔥 Авто велике, габарити відчуваються, але на трасі це плюс всі пропускають і поважають💪🏻", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/photo_2025-07-25_15-01-36.jpg"}]', 'Mercedes-Benz GLS-Class 400 d 4MATIC: Розкіш і Потужність у Великому Форматі', 'Відкрийте світ розкоші з Mercedes-Benz GLS-Class 400 d 4MATIC — елегантним SUV, що вражає потужністю, простором та інноваційними технологіями. Оформіть підписку на авто в Drivovo і насолоджуйтесь комфортом для всієї родини під час кожної поїздки. Станьте володарем Mercedes-Benz GLS-Class 400 d 4MATIC вже сьогодні!');
INSERT INTO public.car_pages VALUES ('e122a448-fe0e-4ae3-a5f8-bff5c286773a', '0e4e5a87-7d15-4e36-92a9-8a39392d915a', 'Porsche Macan Miami Blue', '<p>Porsche Macan оснащений 2.0 л турбованим двигуном на 265 к.с., що дозволяє досягти розгону до 100 км/год за 6,4 секунди. Це автомобіль, який поєднує потужність з точністю в керуванні, забезпечуючи впевненість у будь-яких умовах.</p>

<p>Салон Macan — стильний і комфортний. Віртуальна панель приладів, мультимедіа система з підтримкою Apple CarPlay, адаптивне освітлення, шкіряні сидіння, акустика BOSE — усе для зручності і задоволення в поїздках.</p>

<p>Динамічний преміум-SUV із 265 к.с., повним приводом і 7-ступеневим PDK. Поєднання стилю, керованості та статусу.</p>
<p>✔ повне страхування: КАСКО, ОСЦПВ, GAP, супутниковий трекер<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ trade-in, підтримка 24/7, без вихідних<br />
✔ оформлення без зайвих питань — лише паспорт і права</p>
<p>Macan у підписці — це коли твоя швидкість і наш сервіс працюють як одне ціле</p>
', NULL, '[{"author": "Сергій Костя", "rating": 5, "comment": "Понеділок. Хочу додати чогось позитивного Одним із важливих показників, а також мотивацій, що ринок працює, бізнеси працюють, економіка працює це нові продукти, нові проєкти та бізнеси вцілому. Мав нагоду особисто познайомитись з Solovyov Maxim , CEO Drivovo-Club сервісу авто по підписці. По-перше це дійсно авто по підписці, і вам не потрібно думати ні про що. Від придбання, юридичних моментів, повного обслуговування і подальшої ліквідності авто. По-друге це команда професіоналів та знавців своєї справи. По-третє і для мене це особисто дуже важливо. Якщо ви не знаєте, що вам дійсно потрібно, то спробуйте, сервіс надає тест драйв на день чи два, що дійсно розкриває весь поведінковий патерн, адже за годину-дві, вже проходить ейфорія від нового/іношого авто і вже приходить раціональне повсякденне використання. Porsche Macan Miami blue це TOP", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/495938822_29714734108141302_7411317935823048589_n.jpg"}]', 'Porsche Macan Miami Blue від Drivovo: Підписка на автомобіль зі стилем', 'Drivovo представляє Porsche Macan у відтінку Miami Blue. Насолоджуйтесь 265 к.с., адаптивною пневматичною підвіскою, іонізацією повітря та преміум аудіосистемою BOSE®. Ваш авто на підписку чекає!');
INSERT INTO public.car_pages VALUES ('2e823063-d267-4dea-9ad9-a808ce94ed1e', '96df0494-350f-4d5f-af9e-68ca23b34891', 'Toyota RAV 4 Adventure — це як син маминої подруги!🍦', '<p>Toyota RAV4 — це коли ти обираєш не емоційний шум, а продуману впевненість.<br />
Гібридна версія з 2.5 л (218–222 к.с.) динамічна версія — 8,4 с до сотні.<br />
Це не гонитва за секундоміром, а про комфортне, контрольоване прискорення — навіть коли графік щільний, а настрій вимагає спокою.<br />
RAV4 у підписці — вибір тих, хто звик тримати темп без зайвої метушні.</p>

<p>Салон Toyota RAV4 — це тиша, порядок і функціональність.<br />
Зручна посадка, просторий багажник, якісні матеріали, двозонний клімат, сенсорний дисплей з підтримкою Apple CarPlay та Android Auto, безключовий доступ — усе створено, щоб ти не відволікався.<br />
Комфорт не потребує зайвих пояснень — він відчувається з перших хвилин.<br />
І головне: все це вже включено в авто за підпискою. Ніяких додаткових витрат — лише спокій, стиль і технології, що працюють на тебе.</p>

<p>Гібридний кросовер з 2.5-літровим мотором до 222 к.с. Комфорт, надійність і стиль для міських та міжміських поїздок.</p>
<p>✔ Повне страхування: КАСКО, ОСЦПВ, GAP, трекер<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ Trade-in, супровід на СТО, підтримка 24/7<br />
✔ Оформлення без довідок і кредитних перевірок</p>
<p>Toyota RAV4 у підписці — це спокій, який завжди з тобою</p>
', NULL, '[{"author": "Максим Макаренко", "rating": 5, "comment": "Я просто кайфую, коли бізнеси намагаються надавати сервіси екстра рівня для своїх клієнтів. Як мені здається, overdelivery це найважливіша складова DNA кожної сервісної компанії. Але те, що робить Solovyov Maxim з Drivovo-Club це на мій погляд просто еталон того, як сервісні компанії повинні будувати відносини і комунікацію зі своїми кліентами. Я спостерігаю за Drivovo з першого дня існування і мені дуже імпонує ідеологія та підхід який вони використовують I ось нещодавно я дізнався, що Drivovo вирішили виходити на ринок Польщі і Макс одразу запропонував мені потестити декілька днів новеньку Toyota Rav4. Це вам не якийсь тест-драйв на пів годинки, це реально крута можливість потестити машинку в різних кейсах і подивитись чи підходить вона тобі чи, наприклад, зрозуміти що вона не дуже влазить на твоє паркомісце Дуже круто та зручно, ну і як завжди хлопці довели, що вони все роблять на найвищому рівні Всі знають, що Українські компанії на дві голови вище з точкі зору рівня сервісу порівнюючи з рештою європейських (і не тільки) країн і я дуже пишаюся коли круті компанії які не дивлячись ні на що масштабують бізнес і виходять на нові ринки, щоб показати усім, як треба будувати крутий сервіс. Я впевнений що Drivovo стануть одним з таких крутезних кейсів на ринку Європи вже дуже скоро P.S. Пост не проплачений, це прям щиро від всього серця", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/74356123_2700798443306239_2436547320821579776_n.jpg"}]', 'Ваша машина по підписці: Toyota RAV4 Hybrid від Drivovo — Передові технології та комфорт', 'Замовляйте Toyota RAV4 Hybrid від Drivovo і насолоджуйтесь гібридним приводом, адаптивним круїз-контролем та панорамним оглядом. Відкрийте для себе ефективність і безпеку з авто підпискою.');
INSERT INTO public.car_pages VALUES ('946f421c-829e-403a-ba1c-946459bf6e32', '546ba37f-46cb-44fe-b268-63eada8d9d24', 'Хітяра автопарку DRIVOVO — T-Roc Style!🌟', '<p>VW T-Roc — компактний кросовер із характером.</p>
<p>1.5 TSI — 150 к.с., 250 Нм, 0–100 км/год за 8,4 с</p>
<p>Маневровий, живий і адаптований до міського ритму. Ідеальний для тих, хто шукає динамічний стиль без зайвого пафосу.</p>
<p>T-Roc за підпискою — твоя свобода без кредитів і паперової тяганини.</p>

<p>Всередині — простір, який відчувається більшим, ніж здається.<br />
Цифрова панель Digital Cockpit, мультимедіа з підтримкою Apple CarPlay / Android Auto, двозонний клімат, ергономіка, яка не дратує. Доступні варіанти з панорамним дахом та LED-підсвіткою.</p>
<p>Комфорт — не в розмірі, а в деталях. А з підпискою на VW T-Roc ти отримуєш це одразу, без очікувань.</p>

<p>VW T-Roc — міський кросовер із характером: 150 к.с., маневреність і сучасні технології в компактному форматі. Ідеальний для щоденних пригод.</p>
<p>✔ Повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, гума, шинний сервіс, підмінне авто<br />
✔ Trade-in, консьєрж-супровід, підтримка 24/7<br />
✔ Оформлення без PIT, довідок чи фінконтролю</p>
<p>T-Roc — твоя свобода руху без зайвих клопотів</p>
', NULL, '[{"author": "Назар Чередарик", "rating": 5, "comment": "Помітили, що все тепер існує за підписками ? Нетфлікс, ютуб преміум, спотіфай та інше. Розказую вам про квінтесенцію підписок підписка на машину Drivovo-Club Так сталось, що чув про них раніше, а тепер прямо познайомився і вийшло вже покористуватись сервісом. На фото забираю T-Roc, з яким у нас стався метч Машина 22 року це щось із нанотехнологій, фільтрує повітря, тримає швидкість і смугу сама, інколи спілкується з тобою Про сервіс: ти платиш лише місячний платіж, ну і заправляєшся, звичайно Все решта страховки, ТО, перевзування та інші клопоти завжди залишаються за сервісом Ну і кіллер-фіча зберігання комплекту резини, не треба шукати те саме місце, куди його діти! Дякую Sergey Gvritishvili та https://drivovo.eu/", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/03/Nazar-CHeredaryk.webp"}]', 'Volkswagen T-Roc R-Line від Drivovo: Стиль і динаміка в авто підписці', 'Виберіть новий Volkswagen T-Roc R-Line з Drivovo для динамічного досвіду водіння. Завдяки 150 к.с., спортивним сидінням Premium, і бездротовій зарядці, цей автомобіль ідеально підходить для сучасного життя міста. Насолоджуйтесь перевагами підписки на авто з передовими технологіями безпеки та комфорту');
INSERT INTO public.car_pages VALUES ('ad926c50-ad4e-4199-93e2-adcd9edc5399', 'a6969073-5ada-4784-9901-fa5a3a090af7', 'Audi A6 — бізнес-клас у сучасному форматі підписки', '<p>Audi A6 — бізнес-клас із німецьким акцентом на динаміку.<br />
Доступні версії:</p>
<p>45 TFSI — 2.0 бензин, 265 к.с., 370 Нм, 0–100 км/год за 6,0 с</p>
<p>Кожна поїздка — стабільна, точна, енергійна.<br />
Фірмова ходова, опціональний повний привід quattro та бездоганна шумоізоляція — все для тих, хто цінує темп і тишу одночасно.</p>
<p>Audi A6 в підписці — це впевненість без переплат і зайвих формальностей.</p>

<p>Салон Audi A6 — це продуманий мінімалізм з акцентом на комфорт.<br />
Два сенсорні дисплеї MMI Touch, цифрова панель приладів Virtual Cockpit, підсвічування, трьохзонний клімат-контроль, шкіряні сидіння з підігрівом — у всьому відчувається інженерна виваженість.</p>
<p>Авто за підпискою — це не компроміс, а розумний вибір для тих, хто хоче бізнес-клас без банківських черг.</p>

<p>Audi A6 — динамічний бізнес-седан з повним приводом, бензиновими моторами до 265 к.с. і витриманим комфортом. Для тих, хто цінує точність і стиль.</p>
<p>✔ Повне страхування: КАСКО, ОСЦПВ, GAP, GPS-захист<br />
✔ ТО, сезонна гума, шинний сервіс, підмінне авто<br />
✔ Trade-in, супровід на СТО, підтримка 24/7<br />
✔ Оформлення без перевірок, лише паспорт і права</p>
<p>Audi A6 — це коли кожен кілометр під контролем, а все решта — вже включено</p>
', NULL, '[{"author": "Leah Zanko ", "rating": 5, "comment": "Минулий тиждень був на стілький шалений, тож аби усе встигнути, довелось пересісти на більш потужну тачку Дуже радію, що така можливість є на відстані одного повідомлення: пишеш друзям із Drivovo-Club і нова автівка одразу твоя. Хочу зазначити, що це не просто сервіс оренди, а набагаааато більше. Оформлюючи підписку на автівку в Драйвово, ви отримуєте вирішення усіх ваших проблем, які можуть виникнути в процесі експлуатації ніякого головняку із СТО, витрат часу на заміну резини, жодної вашої залученості у випадку евакуаціі автівки. Якщо із вашою автівкою щось трапилось, ви просто отримуєте підмінне авто, пересідаєте на нього та ганяєте по своїх справах, поки Драйвово вирішує усі питання Оскільки я фанат делегування, мені такий підхід шалено імпонує)) Безмежно вдячна Maksym Soloviov та усій команді Drivovo-Club за нереальний сервіс, можливість приміряти нову автівку, встигнути все, не збавляючи обертів, та каву при кожній зустрічі. Обожнюю", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/07/photo_2025-07-28_13-25-04.jpg"}]', NULL, 'Обирайте Audi A6 за підпискою — стильний та потужний бізнес-седан з передовими технологіями. Користуйтеся авто без кредитів та зайвих турбот.');
INSERT INTO public.car_pages VALUES ('25ca455e-5263-4437-9842-b2153f2c8890', '3b968137-a79e-4cda-b373-497b689da090', 'Занадто гарячий, щоб ігнорувати🔥', '<p>Audi A7 Sportback — витонченість, яка летить.<br />
Доступні версії:</p>
<p>45 TFSI — 2.0 бензин, 265 к.с., 370 Нм, 0–100 км/год за 6,2 с</p>
<p>Плавний, потужний старт і точна керованість. Повний привід quattro, м’який гібрид та продумана аеродинаміка дають більше, ніж просто комфорт — це кероване задоволення.</p>
<p>Audi A7 в підписці — вибір тих, хто хоче бізнес-купе без банківських рішень і довгих контрактів.</p>

<p>Салон Audi A7 — це про преміальний спокій і інтуїтивну технологічність.<br />
Два дисплеї MMI Touch, Virtual Cockpit, аудіо Bang &amp; Olufsen, амбієнтне підсвічування, масаж сидінь (опція), простір у стилі гранд-турера.</p>
<p>Все керується легко і красиво — саме так має виглядати авто за підпискою преміум-класу.</p>

<p>Audi A7 Sportback — це 265 к.с., quattro і аеродинаміка купе. Стриманий дизайн, що рухається елегантно і швидко.</p>
<p>✔ КАСКО, ОСЦПВ, GAP, супутниковий трекер<br />
✔ ТО, сезонна гума, заміни, підмінне авто<br />
✔ Trade-in, підтримка 24/7, сервіс без вихідних<br />
✔ Реєстрація за 29 хв без банківських перевірок</p>
<p>Audi A7 — це коли розкіш і спокій поєднуються в одному русі</p>
', NULL, '[{"author": "Абрамович Ірина", "rating": 5, "comment": "Тапочку в підлогу і не відпускайте, поки я вам не скажу, якщо ви не знали, то це саме та фраза, яка має супроводжуватися нічним тест-драйвом здорової людини. І не 7 хвилин на автопаркінгу, а: Хочу на погану дорогу, Хочу спробувати іншу машину, і більше півгодини на трасі. Виявилось, що в Україні є бізнес, де прийнято робити те, що називається over-delivery. У них не тільки нові авто і чіткі умови, але й не треба нічим паритися: їздиш, заправляєш, миєш, розважаєшся. Drivovo робить решту за вас. Навіть не буду згадувати, що моя нова машина отримала смачне вино та купу крутого мерчу. Краще скажу, що від моменту, коли я натиснула кнопку на сайті до тест-драйву з засновником бізнесу, зайняло близько півгодини. Чи ні, краще, що на другому тест-драйві я прийняла рішення посеред дороги, озвучила його, а у відповідь почула: Ок, давай відразу в автосалон, обираємо колір. А наступного вечора машину привезли прямо до будинку. Ні води, ні витрат мого часу, максимально прозоре спілкування на кожному етапі. Найобразливіше в цьому всьому те, що я не знайшла підвоху (а ми памятаємо, що я заслужений майстер спорту докапатись). Також Solovyov Maxim слухає будь-які відгуки, і дуже швидко і по справі реагує.", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/07/464429918_8754453017951623_4792314032443225160_n.jpg"}]', 'Audi A7 45 TFSI за підпискою — розкіш у русі', 'Audi A7 45 TFSI — купе-седан із 265 к.с., повним приводом та інтелектуальними технологіями. Обирай авто за підпискою — це свобода керування без зобов’язань.');
INSERT INTO public.car_pages VALUES ('01afe548-b478-46cc-8475-796f58a2bdf3', '56f71b72-5a4d-4e9f-b8ed-6e4504e3b7cd', 'Volkswagen Touareg R-Line', '<p>Volkswagen Touareg — SUV для тих, хто хоче більше.<br />
Доступні дизельні варіанти:</p>
<p>3.0 TDI V6 — 286 к.с., крутний момент до 600 Нм,<br />
розгін від 6,1 с до 100 км/год.</p>
<p>Повний привід 4Motion, 8-ступенева автоматична коробка та адаптивна підвіска — Touareg поєднує впевненість бізнес-класу з тягою до пригод.</p>
<p>Підписка на VW Touareg — це розкіш без обов’язків.</p>

<p>Інтер’єр Touareg — преміум із німецькою педантичністю.</p>
<p>Innovision Cockpit: суцільний вигнутий дисплей (до 15&#8243;)<br />
Сидіння ergoComfort з масажем і вентиляцією<br />
Панорамний дах, оздоблення шкірою Vienna чи Savona<br />
Підсвічування на 30 кольорів, преміальна акустика</p>
<p>Комфорт, який вражає — без зайвого пафосу. Touareg за підпискою — коли преміум став доступним.</p>

<p>Touareg — потужний дизельний SUV з двигуном V6, адаптивною підвіскою та повним приводом. Преміум без зобов’язань.</p>
<p>✔ КАСКО, ОСЦПВ, GAP, супутниковий трекер<br />
✔ ТО, гума, шинний сервіс, підмінне авто<br />
✔ Trade-in, консьєрж-сервіс 24/7, оновлення моделі<br />
✔ Оформлення без PIT і фінмоніторингу</p>
<p>VW Touareg — це статус і свобода в одному підписному пакеті</p>
', NULL, '[{"author": "Гольцберг Анна", "rating": 5, "comment": "Темні часи добре розкривають світлих людей та яскраві прекрасні бізнеси. Не важко знайти таких людей і такі бізнеси, просто треба попросити допомоги. Хто має можливість відгукнутися, можна одразу внести до Червоної книги, ну і до власного зошиту, щоб не загубити і подякувати. Тож щиро хочу подякувати сервісу Drivovo, який в найскладніший період війни дав мені змогу здійснювати свою волонтерську роботу. Хлопці без сумніву надали мені новеньке авто і ми змогли продовжити нашу діяльність допомоги самотнім людям похилого віку. Це було цілком і дуже щиро в той момент. А зараз хлопці знову активно працюють і готові бути корисними і вам! Це дійсно унікальний сервіс! Знайомтесь класні, надійні, драйвові та чесні! Детальніше про перший в Україні автосервіс за підпискою Драйвово ви можете дізнатися на сайті https://drivovo.eu", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/07/photo_2025-07-28_13-59-05.jpg"}]', 'VW Touareg за підпискою — преміум SUV без зобов’язань', 'Volkswagen Touareg — потужний і технологічний позашляховик із повним приводом і комфортом бізнес-класу. Доступний за підпискою без переплат.');
INSERT INTO public.car_pages VALUES ('95bb179f-467a-448e-b0cf-1ccde695ad00', '91e038c6-600e-468f-90e8-33cb4674e00f', 'Mercedes-Benz GLE', '<p>Mercedes GLE про потужність, яка дає відчуття контролю. 3.0 л V6 на 320 к.с. розганяє автомобіль до 100 км/год за 6.8 секунди. Плавність розгону, точність у керуванні та стабільність на будь-яких маршрутах — те, що ти отримуєш від цього звіра.</p>

<p>У салоні Mercedes GLE: просторі сидіння з преміальних матеріалів, мультимедійна система з підтримкою Apple CarPlay та Android Auto, адаптивне освітлення, шкіряне оздоблення і акустика Burmester — усе це створює атмосферу комфорту та елегантності. Кожен елемент продуманий, щоб поїздка приносила лише задоволення.</p>

<p>GLE — 320 к.с., повний привід, V6 і адаптивна підвіска. Просторий SUV, який дарує впевненість і статус.</p>
<p>✔ КАСКО, ОСЦПВ, GAP, супутниковий GPS-захист<br />
✔ ТО, гума, шинний сервіс, підмінне авто<br />
✔ trade-in, драйвер-сервіс, цілодобова підтримка<br />
✔ оформлення без довідок, за 29 хв</p>
<p>GLE у підписці — це коли турбота не навʼязується, а просто працює</p>
', NULL, '[{"author": "Савелєв Євген", "rating": 5, "comment": "А тепер про Драйвово. Команда фанати своєї справи! Коли я забирав свою машину у одного з членів їхньої команди Олександра, ми майже годину з ним спілкуватися. Давно не відчував такого захвату і тотальної віддачі! За той короткий час нашого спілкування (так, години точно замало:) я загалом зрозумів, що таке Драйвово. Так ось) Хлопці надають можливість, при досить комфортному першому внеску, взяти авто в користування з щомісячними платежами. Такий собі лізинг АЛЕ, це не класичний лізинг. Тут команда Драйвово бере на себе всі турботи про авто, починаючи від ТО і до зберігання зимових шин! Тобто ви дійсно, просто берете і їдете) Окрім цього, Drivovo організували дуже потужну спільноту однодумців, в якій обмінюються автомобілями, збираються на зустрічі, створюють спільні проекти та проводять час разом І ось, ви поїздили півроку-рік та захотіли змінити авто, це можна зробити дуже просто, а значна частина минулих платежів перерахована на оплату нового авто Ну, мені як лібертаріанському юристу особливо приємно було почути, що підписатися на авто можна буквально за один день, бо процедура апрува дуже ліберальна і проста Ще багато чого можна писати про те, що зробили ці адепти зручності, якості та драйву, але рекомендую просто протестувати, щоб отримати класний та комфортний досвід появи нового авто у вашому житті, з легкістю та задоволенням", "authorImage": "https://drivovo.eu/wp-content/uploads/2025/07/photo_2025-07-28_15-59-00.jpg"}]', 'Mercedes GLC за підпискою — комфорт і стиль без зобов’язань', 'Mercedes-Benz GLC — елегантний SUV з повним приводом, цифровими технологіями та преміальним салоном. Користуйся авто за підпискою — зручно і вигідно.');
INSERT INTO public.car_pages VALUES ('d9e175f1-8e8f-4ac9-935a-7457e4649ed0', 'bf08ea70-70fc-43dd-86af-3d3df2332e4a', 'Cupra Terramar ', '<p>Cupra Terramar оснащений турбованим бензиновим двигуном потужністю до 265 к.с., який розганяє авто до 100 км/год приблизно за 5,5 секунди. Ідеальний варіант для тих, хто цінує швидкість, динаміку і драйв, обираючи авто за підпискою без компромісів.</p>

<p>Сучасний і стильний салон з преміальними матеріалами, повністю цифрова панель приладів, сенсорний екран мультимедіа і розширені можливості підключення. Комфорт і передові технології створюють ідеальне середовище для будь-якої поїздки.</p>

<p>Terramar — до 300 к.с., турбований бензин, адаптивне шасі й повний привід. Сучасний SUV для тих, хто завжди в русі.</p>
<p>✔ КАСКО, GAP, ОСЦПВ, супутниковий трекер<br />
✔ ТО, сезонна гума, підмінне авто<br />
✔ Trade-in, супровід, підтримка 24/7<br />
